// SPDX-License-Identifier: Unlicensed
pragma solidity >=0.0;
contract A { uint256 a; constructor() { a = 1; } }
contract B { uint256 b; constructor() { b = 2; } }
contract C {
    address deployed;
    constructor() { deployed = address(new A()); }
    function make() public returns (address) { return address(new B()); }
}
